mapper.select:
select id, topic_id, activity_id, play_instance_id, owner_member_id,
       quota_total, quota_used, version, create_time, update_time
  from play_help_run_quota
 where topic_id = #{topicId}
   and activity_id = #{activityId}
   and play_instance_id = #{playInstanceId}
   and owner_member_id = #{ownerMemberId}
 limit 1

mapper.update:
update play_help_run_quota
   set quota_used = quota_used + 1,
       version = version + 1,
       update_time = now(3)
 where topic_id = #{topicId}
   and activity_id = #{activityId}
   and play_instance_id = #{playInstanceId}
   and owner_member_id = #{ownerMemberId}
   and quota_used < quota_total
